async function (variables) {
    var userOnboardingGrid = new GridWidget(variables.element, variables.dataSource);
    userOnboardingGrid.columns = [
        { field: "State", type: "string", title: "[resource_shortdisplayname[requestState]]", width: 40, template: "<span class='k-icon #=UserOnboarding.iconStates[State]#'></span>" },
        { field: "email", type: "string", title: "[resource_shortdisplayname[userEmail]]", template: "#=JSON.parse(DataJson).fields[0].email#" },
        { field: "companyName", type: "string", title: "[resource_shortdisplayname[companyName]]", template: "#=JSON.parse(DataJson).fields[1].companyName#" },
        { field: "CreatedOn", type: "date", title: "[resource_shortdisplayname[requestDate]]", width: 80, format: "{0:" + type.dateFormat + "}" },
        { field: "CreatedBy", title: "[resource_shortdisplayname[CreatedBy]]", width: 100 },
        { field: "requestType", type: "string", title: "[resource_shortdisplayname[requestType]]", width: 150, template: "#=JSON.parse(DataJson).fields[2].requestType ? UserOnboarding.requestTypes[JSON.parse(DataJson).fields[2].requestType.value] : ''#" },
    ];
    userOnboardingGrid.editable = false;
    userOnboardingGrid.sortable = false;
    userOnboardingGrid.filterable = false;
    userOnboardingGrid.pageable = false;
    userOnboardingGrid.groupable = false;
    userOnboardingGrid.toolbar = "<button name='addUserOnboardingRequest'><span class='k-icon k-i-plus'></span>[resource_displayname[New]]</button>";
    variables.UserOnboardingGrid = userOnboardingGrid;
    return userOnboardingGrid;
}
